import{_ as e,o as a,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),n={name:"en/guide/index.md"};function i(s,t,l,h,d,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>LLMxRay</strong> is a free, local-first dashboard that connects to <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> running on your machine. It lets you chat with any model you&#39;ve downloaded and then inspect everything that happened behind the scenes: how fast each token arrived, what the model might have been &quot;thinking&quot;, how different settings change the output, and much more.</p><p><strong>No cloud. No API keys. No cost.</strong> Everything runs on your hardware.</p><h2 id="who-is-this-for" tabindex="-1">Who is this for? <a class="header-anchor" href="#who-is-this-for" aria-label="Permalink to &quot;Who is this for?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You are...</th><th>LLMxRay helps you...</th></tr></thead><tbody><tr><td><strong>Curious beginner</strong></td><td>See AI responses form in real time and learn what &quot;temperature&quot; or &quot;tokens&quot; actually mean</td></tr><tr><td><strong>Student / educator</strong></td><td>Explore model behavior visually — great for AI/ML coursework and demos</td></tr><tr><td><strong>Developer</strong></td><td>Debug prompts, compare models, profile latency, inspect tool calls</td></tr><tr><td><strong>Researcher</strong></td><td>Run controlled experiments: same prompt, different settings, side-by-side results</td></tr></tbody></table><h2 id="navigating-the-app" tabindex="-1">Navigating the App <a class="header-anchor" href="#navigating-the-app" aria-label="Permalink to &quot;Navigating the App&quot;">​</a></h2><p>LLMxRay has a sidebar with 12 navigation items, each representing a major feature. This guide has one chapter per item, in the exact order they appear in the sidebar:</p><ol><li><strong><a href="./chat-diagnostics.html">Chat Diagnostics</a></strong> — The main chat interface with streaming and session analysis</li><li><strong><a href="./compare.html">Compare</a></strong> — Side-by-side model and settings comparison <ul><li><strong><a href="./language-compare.html">Language Compare</a></strong> — Understanding the token tax across languages</li></ul></li><li><strong><a href="./embeddings.html">Embeddings</a></strong> — Text embedding visualization and similarity</li><li><strong><a href="./knowledge-base.html">Knowledge Base</a></strong> — Document upload, chunking, and RAG search</li><li><strong><a href="./tool-workshop.html">Tool Workshop</a></strong> — Visual tool builder with code sync</li><li><strong><a href="./fim.html">Fill-in-the-Middle (FIM)</a></strong> — Code completion playground for FIM-capable models</li><li><strong><a href="./protocols.html">Protocol Observatory</a></strong> — Run the same prompt through native, OpenAI-compat, and Anthropic-compat against your local model</li><li><strong><a href="./ai-training.html">AI Training</a></strong> — Training data curation and export</li><li><strong><a href="./models.html">Models</a></strong> — Model browser and capability detection</li><li><strong><a href="./benchmark.html">Benchmark</a></strong> — Standardized model evaluation with logprobs</li><li><strong><a href="./system.html">My System</a></strong> — Hardware detection and Ollama status</li><li><strong><a href="./settings.html">Settings</a></strong> — Connection, parameters, and preferences</li></ol><h2 id="other-elements" tabindex="-1">Other Elements <a class="header-anchor" href="#other-elements" aria-label="Permalink to &quot;Other Elements&quot;">​</a></h2><ul><li><strong>Header bar</strong> — Shows the current page title, a theme toggle (dark/light), and Ollama connection status (green = connected, red = disconnected).</li><li><strong>Feedback button</strong> — At the bottom of the sidebar. Opens an overlay to submit feedback directly.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>If you haven&#39;t installed LLMxRay yet, head to the <a href="./installation.html">Installation</a> page. Otherwise, pick any chapter from the sidebar to start exploring.</p>',12)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
